    <div class="container">
        <div class="header">
            <button class="nav-arrow" id="prev-month">&#10094;</button>
            <div class="month-name" id="month-name"></div>
            <button class="nav-arrow" id="next-month">&#10095;</button>
        </div>

        <table class="calendar" id="calendar">
            <thead>
                <tr id="day-headers"></tr>
            </thead>
            <tbody id="calendar-body"></tbody>
        </table>

        <div class="time-slots" id="time-slots">
            <!-- Time slots will be generated by JS -->
        </div>

        <div class="doctor-info">
            <p id="doctor-name">د. محمد أحمد</p>
        </div>

        <button class="confirm-btn" id="confirm-btn" disabled>Unnamed</button>
    </div>

    <script>
        // Arabic month names
        const monthNames = [
            "يناير", "فبراير", "مارس", "أبريل", "مايو", "يونيو",
            "يوليو", "أغسطس", "سبتمبر", "أكتوبر", "نوفمبر", "ديسمبر"
        ];

        // Arabic day names (starting Saturday)
        const dayNames = [
            "السبت", "الأحد", "الاثنين", "الثلاثاء", "الأربعاء", "الخميس", "الجمعة"
        ];

        // Time slots from 9:00 to 12:00 every 30 minutes
        const timeSlots = [
            "9:00", "9:30", "10:00", "10:30", "11:00", "11:30", "12:00"
        ];

        // Current displayed month and year
        let currentMonth = new Date().getMonth();
        let currentYear = new Date().getFullYear();

        // Selected date and time
        let selectedDate = null;
        let selectedTime = null;

        // Elements
        const monthNameEl = document.getElementById('month-name');
        const calendarBodyEl = document.getElementById('calendar-body');
        const dayHeadersEl = document.getElementById('day-headers');
        const timeSlotsEl = document.getElementById('time-slots');
        const confirmBtn = document.getElementById('confirm-btn');

        // Initialize
        document.addEventListener('DOMContentLoaded', function() {
            renderDayHeaders();
            renderCalendar();
            renderTimeSlots();
            updateMonthName();

            document.getElementById('prev-month').addEventListener('click', goToPreviousMonth);
            document.getElementById('next-month').addEventListener('click', goToNextMonth);
            confirmBtn.addEventListener('click', confirmBooking);
        });

        function renderDayHeaders() {
            dayHeadersEl.innerHTML = '';
            dayNames.forEach(day => {
                const th = document.createElement('th');
                th.textContent = day;
                dayHeadersEl.appendChild(th);
            });
        }

        function renderCalendar() {
            calendarBodyEl.innerHTML = '';

            const firstDay = new Date(currentYear, currentMonth, 1);
            const lastDay = new Date(currentYear, currentMonth + 1, 0);
            const today = new Date();
            today.setHours(0, 0, 0, 0);

            // Calculate starting day index (0 = Saturday)
            let startDayIndex = (firstDay.getDay() + 1) % 7; // Convert Sunday=0 to Saturday=0

            // Create weeks
            let date = 1;
            for (let week = 0; week < 6; week++) {
                const row = document.createElement('tr');
                for (let i = 0; i < 7; i++) {
                    const cell = document.createElement('td');
                    if (week === 0 && i < startDayIndex) {
                        // Empty cell before first day
                        cell.textContent = '';
                    } else if (date <= lastDay.getDate()) {
                        cell.textContent = date;
                        const cellDate = new Date(currentYear, currentMonth, date);
                        cellDate.setHours(0, 0, 0, 0);

                        // Mark today
                        if (cellDate.getTime() === today.getTime()) {
                            cell.classList.add('today');
                        }

                        // Mark selected
                        if (selectedDate && cellDate.getTime() === selectedDate.getTime()) {
                            cell.classList.add('selected');
                        }

                        cell.addEventListener('click', function() {
                            selectDate(cellDate);
                        });

                        date++;
                    } else {
                        // Empty cell after last day
                        cell.textContent = '';
                    }
                    row.appendChild(cell);
                }
                calendarBodyEl.appendChild(row);
            }
        }

        function renderTimeSlots() {
            timeSlotsEl.innerHTML = '';
            timeSlots.forEach(time => {
                const slot = document.createElement('div');
                slot.className = 'time-slot';
                slot.textContent = time;
                if (selectedTime === time) {
                    slot.classList.add('selected');
                }
                slot.addEventListener('click', function() {
                    selectTime(time);
                });
                timeSlotsEl.appendChild(slot);
            });
        }

        function updateMonthName() {
            monthNameEl.textContent = `${monthNames[currentMonth]} ${currentYear}`;
        }

        function selectDate(date) {
            selectedDate = date;
            renderCalendar();
            updateConfirmButton();
        }

        function selectTime(time) {
            selectedTime = time;
            renderTimeSlots();
            updateConfirmButton();
        }

        function updateConfirmButton() {
            confirmBtn.disabled = !(selectedDate && selectedTime);
        }

        function goToPreviousMonth() {
            currentMonth--;
            if (currentMonth < 0) {
                currentMonth = 11;
                currentYear--;
            }
            updateMonthName();
            renderCalendar();
        }

        function goToNextMonth() {
            currentMonth++;
            if (currentMonth > 11) {
                currentMonth = 0;
                currentYear++;
            }
            updateMonthName();
            renderCalendar();
        }

        function confirmBooking() {
            if (selectedDate && selectedTime) {
                const formattedDate = `${selectedDate.getDate()}/${selectedDate.getMonth() + 1}/${selectedDate.getFullYear()}`;
                alert(`Unnamed: ${formattedDate} في ${selectedTime}`);
                // Here you would typically send the booking to the server
            }
        }
    </script>
